//! Fixed Miller-loop coefficients for Ethereum's two KZG G2 points.
//! Regenerated by `cargo run -p jeth-core --example kzg-prepare -- PATH`.

use ark_bls12_381::{Bls12_381, Fq, Fq2};
use ark_ec::pairing::Pairing;
use ark_ff::BigInt;

type Prepared = <Bls12_381 as Pairing>::G2Prepared;
const COEFFICIENTS: usize = 68;
const POINT_BYTES: usize = COEFFICIENTS * 3 * 2 * 6 * 8;
// Decode the checked-in little-endian bytes at compile time so guest loads are
// aligned words, rather than byte loads expanded by the RISC-V prover.
static DATA: [u64; 2 * POINT_BYTES / 8] = {
    let bytes = include_bytes!("g2-prepared.bin");
    let mut words = [0; 2 * POINT_BYTES / 8];
    let mut i = 0;
    while i < words.len() {
        let j = 8 * i;
        words[i] = u64::from_le_bytes([
            bytes[j],
            bytes[j + 1],
            bytes[j + 2],
            bytes[j + 3],
            bytes[j + 4],
            bytes[j + 5],
            bytes[j + 6],
            bytes[j + 7],
        ]);
        i += 1;
    }
    words
};

pub(super) fn fixed_points() -> [Prepared; 2] {
    core::array::from_fn(|point| {
        let mut offset = point * POINT_BYTES / 8;
        let mut field = || {
            let limbs = core::array::from_fn(|_| {
                let limb = DATA[offset];
                offset += 1;
                limb
            });
            Fq::new_unchecked(BigInt(limbs))
        };
        let ell_coeffs = (0..COEFFICIENTS)
            .map(|_| {
                let a = Fq2::new(field(), field());
                let b = Fq2::new(field(), field());
                let c = Fq2::new(field(), field());
                (a, b, c)
            })
            .collect();
        Prepared {
            ell_coeffs,
            infinity: false,
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use ark_bls12_381::G2Affine;
    use ark_ec::AffineRepr;
    use ark_serialize::CanonicalDeserialize;
    use reth_evm::revm::precompile::bls12_381_const::TRUSTED_SETUP_TAU_G2_BYTES;

    #[test]
    #[expect(clippy::unwrap_used, reason = "fixed valid setup point in test")]
    fn coefficients_match_ethereum_setup() {
        let tau = G2Affine::deserialize_compressed(&TRUSTED_SETUP_TAU_G2_BYTES[..]).unwrap();
        for (actual, point) in fixed_points()
            .into_iter()
            .zip([-G2Affine::generator(), tau])
        {
            let expected = Prepared::from(point);
            assert_eq!(actual.ell_coeffs, expected.ell_coeffs);
            assert_eq!(actual.infinity, expected.infinity);
        }
    }
}
